class PDF(FPDF):
    def __init__(self):
        super().__init__()
        self.set_auto_page_break(auto=True, margin=18)

    # -- Header -----------------------------------------------------------------
    def header(self):
        if self.page_no() == 1:
            return
        self.set_font('Helvetica', 'B', 8)
        self.set_text_color(100, 100, 140)
        self.cell(0, 6, 'CAD/CAM Quadruped Robot - Dhruv Khanna', align='L',
                  new_x=XPos.LMARGIN, new_y=YPos.NEXT)
        self.set_draw_color(60, 60, 100)
        self.set_line_width(0.4)
        self.line(self.l_margin, self.get_y(), self.w - self.r_margin, self.get_y())
        self.ln(2)

    # -- Footer -----------------------------------------------------------------
    def footer(self):
        self.set_y(-14)
        self.set_font('Helvetica', '', 7)
        self.set_text_color(120, 120, 160)
        self.cell(0, 5, f'Page {self.page_no()}', align='C')

    # -- Section heading --------------------------------------------------------
    def section(self, title):
        self.ln(4)
        self.set_fill_color(30, 40, 80)
        self.set_text_color(100, 180, 255)
        self.set_font('Helvetica', 'B', 12)
        self.cell(0, 9, title, fill=True, new_x=XPos.LMARGIN, new_y=YPos.NEXT)
        self.set_text_color(30, 30, 30)
        self.ln(2)

    def subsection(self, title):
        self.set_font('Helvetica', 'B', 10)
        self.set_text_color(60, 100, 200)
        self.cell(0, 7, title, new_x=XPos.LMARGIN, new_y=YPos.NEXT)
        self.set_text_color(30, 30, 30)

    def body(self, text, size=9.5):
        self.set_font('Helvetica', '', size)
        self.set_text_color(40, 40, 40)
        self.multi_cell(0, 5.5, text)
        self.ln(1)

    def kv(self, key, val):
        self.set_font('Helvetica', 'B', 9.5)
        self.set_text_color(40, 40, 40)
        self.cell(60, 6, key + ':', new_x=XPos.RIGHT, new_y=YPos.LAST)
        self.set_font('Helvetica', '', 9.5)
        self.cell(0, 6, val, new_x=XPos.LMARGIN, new_y=YPos.NEXT)

    def add_image(self, path, caption='', w=170):
        if os.path.exists(path):
            self.ln(2)
            self.image(path, x=(self.w - w) / 2, w=w)
            if caption:
                self.set_font('Helvetica', 'I', 8)
                self.set_text_color(100, 100, 140)
                self.cell(0, 5, caption, align='C', new_x=XPos.LMARGIN, new_y=YPos.NEXT)
            self.ln(3)
        else:
            self.body(f'[Image not found: {os.path.basename(path)}]')

    def table_row(self, cols, widths, bold=False, fill=False):
        if fill:
            self.set_fill_color(230, 235, 255)
        font = 'B' if bold else ''
        self.set_font('Helvetica', font, 8.5)
        self.set_text_color(30, 30, 30)
        for col, w in zip(cols, widths):
            self.cell(w, 6.5, col, border=1, fill=fill,
                      new_x=XPos.RIGHT, new_y=YPos.LAST)
        self.ln()


